import Foundation

/// Decide si algo copiado se debe guardar. Reglas puras, sin efectos.
public struct CapturePolicy: Sendable {
    /// Marcas estándar de nspasteboard.org que usan los gestores de contraseñas
    /// (1Password, Bitwarden, KeePassXC…) para pedir que no se guarde el contenido.
    public static let privacyMarkerTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        // Marca equivalente que usan algunas apps antiguas.
        "com.agilebits.onepassword",
    ]

    /// Apps que se excluyen al instalar. El usuario puede quitarlas desde Configuración.
    /// Complementa las marcas de privacidad: no todos los gestores las ponen siempre.
    public static let defaultExcludedApps: [SourceApp] = [
        SourceApp(bundleID: "com.apple.Passwords", name: "Contraseñas"),
        SourceApp(bundleID: "com.apple.keychainaccess", name: "Acceso a Llaveros"),
        SourceApp(bundleID: "com.1password.1password", name: "1Password"),
        SourceApp(bundleID: "com.agilebits.onepassword7", name: "1Password 7"),
        SourceApp(bundleID: "com.bitwarden.desktop", name: "Bitwarden"),
    ]

    public enum Decision: Equatable, Sendable {
        case store
        case skip(Reason)
    }

    public enum Reason: Equatable, Sendable {
        case paused
        case privacyMarker
        case excludedApp
        case empty
        case tooLarge
    }

    public var excludedBundleIDs: Set<String>
    public var pause: PauseState
    /// Límite para no llenar el disco con imágenes enormes.
    public var maxImageBytes: Int

    public init(excludedBundleIDs: Set<String> = [], pause: PauseState = .active, maxImageBytes: Int = 25_000_000) {
        self.excludedBundleIDs = excludedBundleIDs
        self.pause = pause
        self.maxImageBytes = maxImageBytes
    }

    public func decide(_ item: CapturedItem) -> Decision {
        if pause.isPaused(at: item.capturedAt) { return .skip(.paused) }
        if !item.pasteboardTypes.isDisjoint(with: Self.privacyMarkerTypes) { return .skip(.privacyMarker) }
        if let bundleID = item.source?.bundleID, excludedBundleIDs.contains(bundleID) {
            return .skip(.excludedApp)
        }
        switch item.payload {
        case .text(let text):
            if text.allSatisfy(\.isWhitespace) { return .skip(.empty) }
        case .image(let png, _, _):
            if png.isEmpty { return .skip(.empty) }
            if png.count > maxImageBytes { return .skip(.tooLarge) }
        }
        return .store
    }
}

/// Estado de pausa de la captura.
public enum PauseState: Hashable, Sendable, Codable {
    case active
    /// Pausado hasta una fecha, o indefinidamente si es `nil`.
    case paused(until: Date?)

    public func isPaused(at date: Date) -> Bool {
        switch self {
        case .active: false
        case .paused(let until): until.map { date < $0 } ?? true
        }
    }
}
